    ('upload_lifecycle_audit', 'upload_lifecycle_audit_pkey', '81b0968b5e0eda3e6f96e2db506dcddf'),
    ('upload_policy_decision_replay', 'upload_policy_decision_replay_pkey', '755eb0f20deff3a62f6b6f0a7df8d2e6'),
