    ('users', 'users_pkey', '6f362412a8d928741cc824b83f94961c')
  ) AS v(tbl, name, md5)),
actual_constraints AS (
  SELECT c.relname::text AS tbl, con.conname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5, regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
    FROM pg_constraint con JOIN pg_class c ON c.oid = con.conrelid
   WHERE c.relnamespace = 'kai'::regnamespace AND c.relname IN ('intake_parser_runs', 'intake_file_profiles', 'data_dictionaries', 'data_dictionary_fields', 'data_dictionary_mappings', 'data_quality_findings', 'intake_sensitivity_profiles', 'intake_sensitivity_review_decisions', 'intake_source_candidates', 'intake_promotion_decisions', 'upload_policy_decision_replay', 'upload_lifecycle_audit', 'sources', 'source_versions', 'source_locators', 'evidence_items', 'claims', 'claim_evidence_links', 'evidence_review_decisions', 'claim_review_decisions', 'coverage_review_decisions', 'gap_log_items', 'client_followup_items', 'conflict_groups', 'review_queue_items', 'generation_runs', 'generated_content_drafts', 'generated_content_blocks', 'generated_content_citations', 'limitation_snapshots', 'limitation_snapshot_entries', 'export_candidates', 'human_authority_decisions', 'export_manifests', 'gk_organization_bindings', 'intake_files', 'audit_events', 'users', 'organizations', 'engagements', 'organization_memberships', 'user_roles', 'roles') AND con.contype <> 'n'
     AND con.conname NOT IN ('evidence_items_p2_01_evidence_type_check', 'evidence_items_p2_01_data_class_check', 'evidence_items_p2_01m_type_class_pairing_check', 'source_locators_p2_01_locator_type_check', 'source_locators_p2_01_coordinates_check', 'intake_sensitivity_review_decisions_b1a_02_role_check', 'limitation_snapshots_p3_16_confirmed_by_role_check', 'human_authority_decisions_p3_17_role_by_type_check', 'generation_runs_p3_01_content_type_check', 'generated_content_drafts_p3_01_content_type_check', 'export_candidates_p3_16_content_type_check', 'upload_lifecycle_audit_gate_a_operation_check')),
actual_columns AS (
  SELECT c.relname::text AS tbl, a.attname::text AS col, regexp_replace(btrim(regexp_replace(regexp_replace(format_type(a.atttypid, a.atttypmod), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS type, a.attnotnull AS nn, a.atthasdef AS has_default
    FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid
   WHERE c.relnamespace = 'kai'::regnamespace AND c.relname IN ('intake_parser_runs', 'intake_file_profiles', 'data_dictionaries', 'data_dictionary_fields', 'data_dictionary_mappings', 'data_quality_findings', 'intake_sensitivity_profiles', 'intake_sensitivity_review_decisions', 'intake_source_candidates', 'intake_promotion_decisions', 'upload_policy_decision_replay', 'upload_lifecycle_audit', 'sources', 'source_versions', 'source_locators', 'evidence_items', 'claims', 'claim_evidence_links', 'evidence_review_decisions', 'claim_review_decisions', 'coverage_review_decisions', 'gap_log_items', 'client_followup_items', 'conflict_groups', 'review_queue_items', 'generation_runs', 'generated_content_drafts', 'generated_content_blocks', 'generated_content_citations', 'limitation_snapshots', 'limitation_snapshot_entries', 'export_candidates', 'human_authority_decisions', 'export_manifests', 'gk_organization_bindings', 'intake_files', 'audit_events', 'users', 'organizations', 'engagements', 'organization_memberships', 'user_roles', 'roles') AND a.attnum > 0 AND NOT a.attisdropped),
actual_triggers AS (
  SELECT c.relname::text AS tbl, t.tgname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_triggerdef(t.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5, regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_triggerdef(t.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def, t.tgenabled::text AS enabled
    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
   WHERE c.relnamespace = 'kai'::regnamespace AND c.relname IN ('intake_parser_runs', 'intake_file_profiles', 'data_dictionaries', 'data_dictionary_fields', 'data_dictionary_mappings', 'data_quality_findings', 'intake_sensitivity_profiles', 'intake_sensitivity_review_decisions', 'intake_source_candidates', 'intake_promotion_decisions', 'upload_policy_decision_replay', 'upload_lifecycle_audit', 'sources', 'source_versions', 'source_locators', 'evidence_items', 'claims', 'claim_evidence_links', 'evidence_review_decisions', 'claim_review_decisions', 'coverage_review_decisions', 'gap_log_items', 'client_followup_items', 'conflict_groups', 'review_queue_items', 'generation_runs', 'generated_content_drafts', 'generated_content_blocks', 'generated_content_citations', 'limitation_snapshots', 'limitation_snapshot_entries', 'export_candidates', 'human_authority_decisions', 'export_manifests', 'gk_organization_bindings', 'intake_files', 'audit_events', 'users', 'organizations', 'engagements', 'organization_memberships', 'user_roles', 'roles') AND NOT t.tgisinternal
     AND t.tgname NOT IN ('trg_organization_release_limitation_snapshot_scope', 'trg_organization_release_decision_scope')),
actual_unique_indexes AS (
  SELECT tablename::text AS tbl, indexname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5, regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
    FROM pg_indexes WHERE schemaname = 'kai' AND tablename IN ('intake_parser_runs', 'intake_file_profiles', 'data_dictionaries', 'data_dictionary_fields', 'data_dictionary_mappings', 'data_quality_findings', 'intake_sensitivity_profiles', 'intake_sensitivity_review_decisions', 'intake_source_candidates', 'intake_promotion_decisions', 'upload_policy_decision_replay', 'upload_lifecycle_audit', 'sources', 'source_versions', 'source_locators', 'evidence_items', 'claims', 'claim_evidence_links', 'evidence_review_decisions', 'claim_review_decisions', 'coverage_review_decisions', 'gap_log_items', 'client_followup_items', 'conflict_groups', 'review_queue_items', 'generation_runs', 'generated_content_drafts', 'generated_content_blocks', 'generated_content_citations', 'limitation_snapshots', 'limitation_snapshot_entries', 'export_candidates', 'human_authority_decisions', 'export_manifests', 'gk_organization_bindings', 'intake_files', 'audit_events', 'users', 'organizations', 'engagements', 'organization_memberships', 'user_roles', 'roles') AND indexdef LIKE 'CREATE UNIQUE INDEX%'),
checks(seq, section, check_id, status, expected, observed, detail) AS (
  SELECT 101, 'A_ENVIRONMENT', 'A01', CASE WHEN to_regnamespace('kai') IS NOT NULL THEN 'PASS' ELSE 'FAIL' END,
              'schema kai exists', coalesce(to_regnamespace('kai')::text, '(absent)'), 'Connected to the production database that holds the KAI schema'
  UNION ALL
  SELECT 102, 'A_ENVIRONMENT', 'A02', CASE WHEN current_setting('server_version_num')::int >= 130000 THEN 'PASS' ELSE 'FAIL' END,
              'PostgreSQL 13 or later (built-in gen_random_uuid, used by 03)', version(), 'Server version (production version is otherwise not recorded in the repository)'
  UNION ALL
  SELECT 103, 'A_ENVIRONMENT', 'A03', CASE WHEN x.missing IS NULL THEN 'PASS' ELSE 'FAIL' END,
              'current_user may ALTER (owns, or is a member of the owner role of) every table the migrations alter',
              'current_user=' || current_user || coalesce('; cannot alter: ' || x.missing, ''),
              'ALTER TABLE requires table ownership; without it the migration fails part-way and rolls back'
         FROM (SELECT string_agg(t, ', ') AS missing FROM unnest(ARRAY['evidence_items', 'source_locators', 'intake_sensitivity_review_decisions', 'limitation_snapshots', 'human_authority_decisions']) t
                WHERE to_regclass('kai.' || t) IS NULL
                   OR NOT pg_has_role(current_user, (SELECT relowner FROM pg_class WHERE oid = to_regclass('kai.' || t)), 'MEMBER')) x
  UNION ALL
  SELECT 104, 'A_ENVIRONMENT', 'A04', CASE WHEN has_schema_privilege('kai', 'CREATE') AND x.missing IS NULL THEN 'PASS' ELSE 'FAIL' END,
              'CREATE on schema kai; REFERENCES on every foreign-key target',
              'create_on_kai=' || has_schema_privilege('kai', 'CREATE')::text || coalesce('; no REFERENCES on: ' || x.missing, ''),
              'Needed by 01 and 03 (new tables with foreign keys) and 04 (new functions)'
         FROM (SELECT string_agg(t, ', ') AS missing FROM unnest(ARRAY['source_versions', 'evidence_items', 'intake_file_profiles', 'generated_content_drafts', 'export_candidates']) t
                WHERE to_regclass('kai.' || t) IS NULL OR NOT has_table_privilege(to_regclass('kai.' || t), 'REFERENCES')) x
  UNION ALL
  SELECT 105, 'A_ENVIRONMENT', 'A05', 'INFO',
              'any migration-history ledger relation (informational; none is defined in the repository)',
              coalesce((SELECT string_agg(n.nspname || '.' || c.relname, ', ' ORDER BY 1)
                          FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
                         WHERE c.relkind IN ('r', 'p', 'v') AND n.nspname NOT IN ('pg_catalog', 'information_schema')
                           AND (c.relname ILIKE '%migrat%' OR c.relname ILIKE '%schema_version%' OR c.relname ILIKE '%flyway%' OR c.relname ILIKE 'knex%')), '(none found)'),
              'If a ledger is listed, send its name; this packet decides state from catalog objects, not from a ledger'
  UNION ALL
  SELECT 201, 'B_PREREQUISITES', 'B01', CASE WHEN x.missing IS NULL THEN 'PASS' ELSE 'FAIL' END,
              'foreign-key and trigger dependencies of the four migrations exist',
              coalesce('missing: ' || x.missing, 'all present'),
              'P2-01M needs unique (source_version_id, organization_id) on source_versions and evidence_items_p2_01_id_org_unique; P1 downstream needs the six-column intake_file_profiles key; release-authority reads content_type/requested_audience'
         FROM (SELECT string_agg(item, ', ') AS missing FROM (
           SELECT 'unique source_versions(source_version_id, organization_id)' AS item WHERE NOT EXISTS (
             SELECT 1 FROM pg_constraint c WHERE c.conrelid = to_regclass('kai.source_versions') AND c.contype IN ('u', 'p')
                AND (SELECT array_agg(a.attname::text ORDER BY a.attname) FROM pg_attribute a WHERE a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)) = ARRAY['organization_id', 'source_version_id'])
           UNION ALL SELECT 'evidence_items_p2_01_id_org_unique' WHERE NOT EXISTS (
             SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01_id_org_unique' AND contype = 'u')
           UNION ALL SELECT 'unique intake_file_profiles(file_profile_id, organization_id, intake_file_id, parser_name, parser_version, checksum)' WHERE NOT EXISTS (
             SELECT 1 FROM pg_constraint c WHERE c.conrelid = to_regclass('kai.intake_file_profiles') AND c.contype IN ('u', 'p')
                AND (SELECT array_agg(a.attname::text ORDER BY a.attname) FROM pg_attribute a WHERE a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey))
                    = ARRAY['checksum', 'file_profile_id', 'intake_file_id', 'organization_id', 'parser_name', 'parser_version'])
           UNION ALL SELECT 'limitation_snapshots_p3_16_confirmed_by_role_check' WHERE NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'limitation_snapshots_p3_16_confirmed_by_role_check')
           UNION ALL SELECT 'human_authority_decisions_p3_17_role_by_type_check' WHERE NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'human_authority_decisions_p3_17_role_by_type_check')
           UNION ALL SELECT 'kai.' || t || '.' || c FROM (VALUES ('generated_content_drafts', 'content_type'), ('generated_content_drafts', 'requested_audience'),
                  ('generated_content_drafts', 'generated_content_draft_id'), ('export_candidates', 'content_type'), ('export_candidates', 'requested_audience'),
                  ('export_candidates', 'export_candidate_id'), ('source_versions', 'is_current')) AS req(t, c)
            WHERE NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('kai.' || t) AND attname = c AND NOT attisdropped)
         ) m) x
  UNION ALL
  SELECT 202, 'B_PREREQUISITES', 'B02', CASE WHEN x.bad IS NULL THEN 'PASS' ELSE 'FAIL' END,
              '16 trigger/CHECK helper functions identical to the 2026-09-16 production capture',
              coalesce(x.bad, 'all identical'), 'Append-only, audience, lifecycle and metadata-only guards the workflow relies on'
         FROM (SELECT string_agg(e.name || CASE WHEN a.md5 IS NULL THEN ' missing' ELSE ' changed' END, ', ' ORDER BY e.name) AS bad
                 FROM (VALUES
      ('b1a_02_reject_sensitivity_review_decision_mutation', '', 'bcfea2f8fd68fe91eb413c4d0fe6de3d'),
      ('enforce_gate_a_p0_upload_lifecycle', '', 'bca9b826000c1b5c25cf9ab95e0e1c3f'),
      ('enforce_gate_c1_gcs_generation_binding', '', '9547f1d17c06ae517c0776bcfb5db4c9'),
      ('gate_a_p0_jsonb_metadata_only', 'value jsonb', 'd00e58efe36939f9ced4e7c0710e3d14'),
      ('p2_10_reject_coverage_decision_mutation', '', '2530ba74fcc6d3fd25875aea9554d1eb'),
      ('p2_12_all_array_entries_non_blank', 'entries text[]', '70713e66cd77aa83a59d4871a1866e61'),
      ('p2_12_reject_claim_review_decision_mutation', '', '3dd3127d377d4bfc16972c81473f85eb'),
      ('p2_12_reject_evidence_review_decision_mutation', '', 'c7271771cbd0fa1ea591cd43ef001f1a'),
      ('p3_16_limitation_codes_valid', 'codes text[]', '82d76e7869015837563b3aae44e63022'),
      ('p3_16_reject_authority_mutation', '', '6a100507eeaf3d71d24750930a035e03'),
      ('p3_17_enforce_decision_audience_compatibility', '', 'd6a40375cbd7443619af0b3938f5a194'),
      ('p3_17_reject_authority_mutation', '', 'dce67f6c9a56cb8c1891fa50d065ab00'),
      ('p3_19_reject_authority_mutation', '', 'c893d83d37206ce6f1cbd69516c7ff42'),
      ('review_queue_items_p1_06_touch_updated_at', '', '9e9e8e590f9929aa722630bd3a2d3ddb'),
      ('set_updated_at', '', '94310db4bba98f08fa9d02f618fcba2b'),
      ('touch_gk_organization_bindings_updated_at', '', '38013b4e1324407b7763a30bb59feaf8')
    ) AS e(name, args, md5)
                 LEFT JOIN (SELECT p.proname::text AS name, pg_get_function_identity_arguments(p.oid) AS args, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_functiondef(p.oid), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5
                              FROM pg_proc p WHERE p.pronamespace = 'kai'::regnamespace AND p.prokind = 'f') a ON a.name = e.name AND a.args = e.args
                WHERE a.md5 IS DISTINCT FROM e.md5) x
  UNION ALL
  SELECT 203, 'B_PREREQUISITES', 'B03.1',
              CASE WHEN s.lits @> ARRAY['evidence_summary', 'impact_narrative', 'readiness_assessment', 'data_gap_memo'] AND s.lits <@ ARRAY['evidence_summary', 'impact_narrative', 'readiness_assessment', 'data_gap_memo', 'case_for_support', 'board_update', 'annual_report_section', 'funder_outcome_table', 'grant_response_paragraph'] THEN 'PASS' ELSE 'FAIL' END,
              'generation_runs_p3_01_content_type_check admits evidence_summary (and the four P3 types); later P13 extensions are accepted',
              coalesce(array_to_string(s.lits, ','), '(absent)'),
              'Content types beyond the base four come from the optional P13 extension migrations, which this workflow does not need'
         FROM (SELECT (SELECT coalesce(array_agg(DISTINCT x ORDER BY x), '{}') FROM (
          SELECT m[1] AS x FROM regexp_matches((SELECT pg_get_constraintdef(oid, true) FROM pg_constraint WHERE conrelid = to_regclass('kai.generation_runs') AND conname = 'generation_runs_p3_01_content_type_check'), '''([a-z0-9_]+)''', 'g') AS m
          UNION ALL
          SELECT unnest(string_to_array(m[1], ',')) FROM regexp_matches((SELECT pg_get_constraintdef(oid, true) FROM pg_constraint WHERE conrelid = to_regclass('kai.generation_runs') AND conname = 'generation_runs_p3_01_content_type_check'), '''\{([a-z0-9_,]+)\}''', 'g') AS m
        ) lit) AS lits) s
  UNION ALL
  SELECT 204, 'B_PREREQUISITES', 'B03.2',
              CASE WHEN s.lits @> ARRAY['evidence_summary', 'impact_narrative', 'readiness_assessment', 'data_gap_memo'] AND s.lits <@ ARRAY['evidence_summary', 'impact_narrative', 'readiness_assessment', 'data_gap_memo', 'case_for_support', 'board_update', 'annual_report_section', 'funder_outcome_table', 'grant_response_paragraph'] THEN 'PASS' ELSE 'FAIL' END,
              'generated_content_drafts_p3_01_content_type_check admits evidence_summary (and the four P3 types); later P13 extensions are accepted',
              coalesce(array_to_string(s.lits, ','), '(absent)'),
              'Content types beyond the base four come from the optional P13 extension migrations, which this workflow does not need'
         FROM (SELECT (SELECT coalesce(array_agg(DISTINCT x ORDER BY x), '{}') FROM (
          SELECT m[1] AS x FROM regexp_matches((SELECT pg_get_constraintdef(oid, true) FROM pg_constraint WHERE conrelid = to_regclass('kai.generated_content_drafts') AND conname = 'generated_content_drafts_p3_01_content_type_check'), '''([a-z0-9_]+)''', 'g') AS m
          UNION ALL
          SELECT unnest(string_to_array(m[1], ',')) FROM regexp_matches((SELECT pg_get_constraintdef(oid, true) FROM pg_constraint WHERE conrelid = to_regclass('kai.generated_content_drafts') AND conname = 'generated_content_drafts_p3_01_content_type_check'), '''\{([a-z0-9_,]+)\}''', 'g') AS m
        ) lit) AS lits) s
  UNION ALL
  SELECT 205, 'B_PREREQUISITES', 'B03.3',
              CASE WHEN s.lits @> ARRAY['evidence_summary', 'impact_narrative', 'readiness_assessment', 'data_gap_memo'] AND s.lits <@ ARRAY['evidence_summary', 'impact_narrative', 'readiness_assessment', 'data_gap_memo', 'case_for_support', 'board_update', 'annual_report_section', 'funder_outcome_table', 'grant_response_paragraph'] THEN 'PASS' ELSE 'FAIL' END,
              'export_candidates_p3_16_content_type_check admits evidence_summary (and the four P3 types); later P13 extensions are accepted',
