              'Content types beyond the base four come from the optional P13 extension migrations, which this workflow does not need'
         FROM (SELECT (SELECT coalesce(array_agg(DISTINCT x ORDER BY x), '{}') FROM (
          SELECT m[1] AS x FROM regexp_matches((SELECT pg_get_constraintdef(oid, true) FROM pg_constraint WHERE conrelid = to_regclass('kai.export_candidates') AND conname = 'export_candidates_p3_16_content_type_check'), '''([a-z0-9_]+)''', 'g') AS m
          UNION ALL
          SELECT unnest(string_to_array(m[1], ',')) FROM regexp_matches((SELECT pg_get_constraintdef(oid, true) FROM pg_constraint WHERE conrelid = to_regclass('kai.export_candidates') AND conname = 'export_candidates_p3_16_content_type_check'), '''\{([a-z0-9_,]+)\}''', 'g') AS m
        ) lit) AS lits) s
  UNION ALL
  SELECT 206, 'B_PREREQUISITES', 'B04', CASE WHEN x.missing IS NULL THEN 'PASS' ELSE 'FAIL' END,
              'upload_lifecycle_audit operation vocabulary admits the 35 operations of the 2026-09-16 production capture',
              coalesce('missing: ' || x.missing, 'all admitted') || coalesce('; additional: ' || x.extra, ''),
              'Every intake, P1, sensitivity, evidence, claim, generation, factual-review and release step writes one of these operations'
         FROM (SELECT (SELECT string_agg(op, ', ' ORDER BY op) FROM unnest(ARRAY['abandon_upload', 'block_upload', 'claim_gap_and_followup_generated', 'claim_proposed', 'claim_review_completed_internal_approval', 'client_followup_completed', 'complete_object_version', 'confirm_upload', 'conflict_review_candidate_created', 'coverage_review_decision_accepted_funder_with_limitation', 'coverage_review_decision_accepted_internal_with_limitation', 'coverage_review_decision_accepted_public_with_limitation', 'data_dictionary_draft_persisted', 'evidence_lineage_extracted', 'evidence_review_completed', 'expire_upload', 'export_candidate_created', 'export_review_completed', 'export_review_requested', 'export_review_started', 'file_profile_persisted', 'generated_content_draft_created', 'generated_content_review_completed', 'generated_content_review_started', 'human_authority_decision_recorded', 'intake_sensitivity_profile_persisted', 'intake_source_candidate_persisted', 'limitation_snapshot_confirmed', 'parser_run_recorded', 'policy_decision_compare_and_set', 'reserve_upload', 'sensitivity_review_decision_recorded', 'sensitivity_review_queue_item_created', 'source_promotion_decision_persisted', 'start_upload']) op WHERE NOT op = ANY (s.lits)) AS missing,
                      (SELECT string_agg(op, ', ' ORDER BY op) FROM unnest(s.lits) op WHERE NOT op = ANY (ARRAY['abandon_upload', 'block_upload', 'claim_gap_and_followup_generated', 'claim_proposed', 'claim_review_completed_internal_approval', 'client_followup_completed', 'complete_object_version', 'confirm_upload', 'conflict_review_candidate_created', 'coverage_review_decision_accepted_funder_with_limitation', 'coverage_review_decision_accepted_internal_with_limitation', 'coverage_review_decision_accepted_public_with_limitation', 'data_dictionary_draft_persisted', 'evidence_lineage_extracted', 'evidence_review_completed', 'expire_upload', 'export_candidate_created', 'export_review_completed', 'export_review_requested', 'export_review_started', 'file_profile_persisted', 'generated_content_draft_created', 'generated_content_review_completed', 'generated_content_review_started', 'human_authority_decision_recorded', 'intake_sensitivity_profile_persisted', 'intake_source_candidate_persisted', 'limitation_snapshot_confirmed', 'parser_run_recorded', 'policy_decision_compare_and_set', 'reserve_upload', 'sensitivity_review_decision_recorded', 'sensitivity_review_queue_item_created', 'source_promotion_decision_persisted', 'start_upload'])) AS extra
                 FROM (SELECT (SELECT coalesce(array_agg(DISTINCT x ORDER BY x), '{}') FROM (
          SELECT m[1] AS x FROM regexp_matches((SELECT pg_get_constraintdef(oid, true) FROM pg_constraint WHERE conrelid = to_regclass('kai.upload_lifecycle_audit') AND conname = 'upload_lifecycle_audit_gate_a_operation_check'), '''([a-z0-9_]+)''', 'g') AS m
